import{c as a,$ as t,Q as l,j as e,g as s,o as i,n,m as c}from"./chunks/framework.Ce_49mA8.js";const k=JSON.parse('{"title":"Производство (Верстак)","description":"Диспетчеризация цеха, управление динамической очередью сборки, каскадное резервирование сырья и выпуск готовой продукции в ОмниКрафт ЕРП.","frontmatter":{"title":"Производство (Верстак)","description":"Диспетчеризация цеха, управление динамической очередью сборки, каскадное резервирование сырья и выпуск готовой продукции в ОмниКрафт ЕРП.","datePublished":"2026-11-15","dateModified":"2026-11-15","order":7},"headers":[],"relativePath":"ru/docs/spaces/production/workbench.md","filePath":"ru/docs/spaces/production/workbench.md","lastUpdated":1794700800000}'),d={name:"ru/docs/spaces/production/workbench.md"},p={id:"производство-верстак-и-очередь-заказов",tabindex:"-1"};function g(h,o,u,m,b,v){const r=t("DocIcon");return l(),e("div",null,[s("h1",p,[i(r,{name:"workbench"}),o[0]||(o[0]=n(" Производство: Верстак и очередь заказов ",-1)),o[1]||(o[1]=s("a",{class:"header-anchor",href:"#производство-верстак-и-очередь-заказов","aria-label":'Permalink to "Производство: Верстак и очередь заказов"'},"​",-1))]),o[2]||(o[2]=c('<p>В ремесленном деле и штучном производстве на стыке планирования и сборки всегда возникает хаос: если материалы списаны в учетной таблице заранее, склад показывает неверные остатки для срочных заказов; если сырье не зарезервировано, на одну и ту же партию кожи или фурнитуры претендуют сразу несколько изделий. В результате мастер либо останавливает работу из-за внезапного дефицита, либо зарывает оборотные средства в избыточные страховые запасы.</p><p>Вкладка <strong>«Производство»</strong> (Верстак) в <strong>ОмниКрафт ЕРП</strong> представляет собой интеллектуальный диспетчерский пульт мастерской. Сюда стекаются все партии, запланированные во вкладке <strong>«Калькулятор»</strong>. Главное инженерное преимущество Верстака — <strong>динамическое каскадное планирование без жестких блокировок складских остатков</strong>.</p><hr><h2 id="принцип-мягкого-резервирования-сырья" tabindex="-1">Принцип мягкого резервирования сырья <a class="header-anchor" href="#принцип-мягкого-резервирования-сырья" aria-label="Permalink to &quot;Принцип мягкого резервирования сырья&quot;">​</a></h2><p>В отличие от громоздких заводских систем, где постановка заказа в план намертво блокирует номенклатурные позиции на складе, ОмниКрафт ЕРП применяет принцип «мягкого резерва».</p><p>При нажатии кнопки <strong>«Запустить в производство»</strong> в Калькуляторе материалы <strong>не списываются со склада физически</strong>. Программа создает в оперативной памяти виртуальный резерв, оценивая доступность сырья в реальном времени.</p><p>Это открывает создателю полную свободу маневра:</p><ul><li>Вы можете формировать производственный график на недели вперед, даже если нужные материалы еще не закуплены или находятся в пути от поставщика.</li><li>Складские остатки в разделе <strong>«Материалы»</strong> остаются чистыми и отражают фактическое физическое наличие на полках мастерской.</li><li>Если приоритеты мастерской внезапно изменились, любой заказ можно мгновенно перестроить в очереди или отменить без мучительного оформления возвратных складских накладных.</li></ul><hr><h2 id="динамическая-очередь-и-каскадныи-приоритет" tabindex="-1">Динамическая очередь и каскадный приоритет <a class="header-anchor" href="#динамическая-очередь-и-каскадныи-приоритет" aria-label="Permalink to &quot;Динамическая очередь и каскадный приоритет&quot;">​</a></h2><p>Очередь Верстака функционирует по закону <strong>каскадного распределения ресурсов сверху вниз</strong>. Программа сканирует физические остатки сырья на складе и последовательно распределяет их между заказами в зависимости от их порядкового номера в списке.</p><p>Каждая карточка заказа в очереди получает один из двух статусов:</p><ol><li><strong>«✅ Обеспечен материалами»</strong> — на складе хватает свободного складского запаса всех требуемых компонентов с учетом потребностей заказов, расположенных выше в очереди.</li><li><strong>«⚠️ Дефицит сырья»</strong> — программа четко указывает наименование недостающих материалов и объем дефицита в базовых единицах измерения (<code>кв. дм</code>, <code>пог. м</code>, <code>кг</code>, <code>шт</code>).</li></ol><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Принцип диспетчеризации</span><div class="formula-heading">Каскадное распределение складского запаса по приоритету</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Свободный остаток</span><span class="math-op">=</span><span class="math-var">Физический склад</span><span class="math-op">−</span><span class="math-var">Сумма резервов заказов выше по очереди</span></div></div></div><h3 id="практическии-пример-управление-приоритетом-заказов" tabindex="-1">Практический пример: Управление приоритетом заказов <a class="header-anchor" href="#практическии-пример-управление-приоритетом-заказов" aria-label="Permalink to &quot;Практический пример: Управление приоритетом заказов&quot;">​</a></h3><p>Представьте реальную производственную ситуацию в кожевенной мастерской:</p><ul><li>На складе числится свободный остаток: <code>100 кв. дм</code> кожи растительного дубления.</li><li>В очередь на Верстак отправлены два заказа: <ol><li><em>Дорожная сумка</em> (требуется <code>80 кв. дм</code> кожи);</li><li><em>Городской рюкзак</em> (требуется <code>90 кв. дм</code> кожи).</li></ol></li></ul><p>Если в списке Верстака <em>Сумка</em> находится выше <em>Рюкзака</em>, система выделит <code>80 кв. дм</code> под Сумку (статус: <strong>Обеспечен материалами</strong>). Для Рюкзака останется лишь <code>20 кв. дм</code>, и программа выведет статус: <strong>Дефицит сырья: Кожа (70.0 кв. дм)</strong>.</p><p>Если заказчик Рюкзака внес срочную доплату, мастер нажимает кнопку-стрелку <strong>«Поднять в очереди»</strong> (↑) на карточке Рюкзака. Система мгновенно пересчитывает баланс сверху вниз: теперь Рюкзак забирает <code>90 кв. дм</code> кожи и становится зеленым, а Сумка опускается ниже и уходит в статус дефицита (<code>70 кв. дм</code>).</p><div class="tip custom-block"><p class="custom-block-title">Совет мастера: Планирование при нулевом складском запасе</p><p>Вы можете смело заводить на Верстак заказы под будущие поставки. Как только во вкладке «Материалы» будет проведена приходная накладная от поставщика, красные индикаторы дефицита на Верстаке моментально станут зелеными без каких-либо дополнительных действий с Вашей стороны.</p></div><hr><h2 id="анатомия-карточки-производственного-задания" tabindex="-1">Анатомия карточки производственного задания <a class="header-anchor" href="#анатомия-карточки-производственного-задания" aria-label="Permalink to &quot;Анатомия карточки производственного задания&quot;">​</a></h2><p>Каждый заказ на Верстаке оформлен в виде автономной карточки с полным набором инструментов диспетчера:</p><ul><li><strong>Блок перемещения в очереди:</strong> Кнопки <strong>«Поднять в очереди»</strong> (↑) и <strong>«Опустить в очереди»</strong> (↓). Верхняя кнопка неактивна для первого заказа списка, нижняя — для замыкающего.</li><li><strong>Информационный блок:</strong><ul><li>Наименование изделия из технологической карты;</li><li>Объем партии (например, <em>«Количество: 5 шт»</em>);</li><li>Точная дата и время запуска задания в работу;</li><li>Оценочная себестоимость партии (плановый расчет на основе норм расхода и актуальных складских цен);</li><li>Динамический статус обеспеченности сырьем.</li></ul></li><li><strong>Интеллектуальный ИИ-ассистент (кнопка с иконкой искры):</strong> Запускает экспресс-анализ производственного задания. Нейросеть оценит готовность сырья, сопоставит плановые затраты с объемами выпуска и выдаст рекомендации по технологической последовательности сборки.</li><li><strong>Кнопка «Отменить»:</strong> Вызывает диалоговое окно подтверждения отмены задания. При подтверждении заказ удаляется с Верстака, а весь зарезервированный под него объем материалов мгновенно высвобождается и распределяется между нижестоящими заказами.</li><li><strong>Кнопка «Завершить»:</strong> Запускает процедуру физического выпуска партии и оприходования готовых товаров.</li></ul><hr><h2 id="физика-завершения-производства-выпуск-готовои-продукции" tabindex="-1">Физика завершения производства (Выпуск готовой продукции) <a class="header-anchor" href="#физика-завершения-производства-выпуск-готовои-продукции" aria-label="Permalink to &quot;Физика завершения производства (Выпуск готовой продукции)&quot;">​</a></h2><p>Когда партия изделий физически собрана на рабочем столе, прошла шлифовку, покраску и выходной контроль качества, мастер нажимает кнопку <strong>«Завершить»</strong>.</p><p>В эту секунду программа выполняет единую атомарную транзакцию в базе данных SQLite:</p><ol><li><strong>Фактическое списание сырья:</strong> Со склада списываются строго материалы изделия (<code>usage_type == &#39;product&#39;</code>). Упаковочные материалы (коробки, тишью, бирки) не затрагиваются — они остаются на складе до момента продажи. В журнале складского учета фиксируется расходная запись с основанием <em>«Расход: Производство [Название] x[Количество]»</em>.</li><li><strong>Заморозка исторической себестоимости:</strong> Программа выполняет точный расчет себестоимости единицы на момент выпуска с учетом актуальных средневзвешенных цен материалов по методу скользящей средней стоимости (МАК), нормы времени мастера и накладных расходов. Полученная цифра <strong>навсегда замораживается</strong> для данной партии.</li><li><strong>Зачисление партии готовой продукции (ФИФО):</strong> Выпущенный тираж приходуется на склад готовых изделий (вкладка «Товары») отдельной независимой партией с фиксацией номера производственного заказа и замороженной себестоимости.</li><li><strong>Закрытие задания:</strong> Статус заказа переводится в завершенный, фиксируется точное время окончания работ, а задание убирается с активного Верстака.</li></ol><ol class="craft-list-steps"><li><div><strong>Списание сырья изделия со склада:</strong><br> Формирование расходной записи в журнале инвентаризации без преждевременного списания упаковочных материалов. </div></li><li><div><strong>Фиксация исторической себестоимости:</strong><br> Точный расчёт и заморозка себестоимости единицы (МАК + труд + накладные) для создаваемой партии. </div></li><li><div><strong>Формирование партии готовой продукции:</strong><br> Оприходование тиража на склад готовых изделий с независимым учётом по методу ФИФО. </div></li><li><div><strong>Закрытие производственного задания:</strong><br> Фиксация времени окончания работ, перевод статуса в завершённый и архивация карточки на Верстаке. </div></li></ol><div class="info custom-block"><p class="custom-block-title">Физика учета: Защита исторической стоимости методом первых партий (ФИФО)</p><p>Представьте, что в понедельник мастер сшил партию из 3 ремней из кожи по старой цене закупки (себестоимость партии составила <code>1 800 руб.</code> за штуку). В пятницу поступила новая шкура по более высокой цене, и мастер выпустил еще 3 таких же ремня (себестоимость составила <code>2 200 руб.</code> за штуку).</p><p>На складе готовых изделий будут числиться 6 одинаковых ремней. Когда покупатель оформит заказ во вкладке «Продажи», программа спишет сначала ремни из первой партии по <code>1 800 руб.</code>, а затем — из второй по <code>2 200 руб.</code> благодаря <strong>методу первых партий (ФИФО)</strong>. Финансовый отчет покажет безупречно честную коммерческую прибыль без усреднения и искажений.</p></div><div class="warning custom-block"><p class="custom-block-title">Технологический сбой: Допуск отрицательного остатка по сырью</p><p>ОмниКрафт ЕРП уважает непрерывность реального производства. Если мастер забыл внести в программу вчерашнюю накладную на поставку клея или фурнитуры, программа не станет блокировать выпуск партии. Склад сырья уйдет в технический отрицательный остаток, а готовые изделия будут своевременно оприходованы. Когда вы внесете накладную позже, баланс автоматически сойдется.</p></div><hr><h2 id="ограничения-ознакомительного-режима-демо-версия" tabindex="-1">Ограничения ознакомительного режима (Демо-версия) <a class="header-anchor" href="#ограничения-ознакомительного-режима-демо-версия" aria-label="Permalink to &quot;Ограничения ознакомительного режима (Демо-версия)&quot;">​</a></h2><p>В бесплатной ознакомительной версии программы действует порог в <strong>20 проведенных коммерческих операций (чеков продаж)</strong>:</p><ul><li>При превышении порога в верхней части Верстака появляется предупреждающий баннер <strong>«Достигнут лимит ознакомительной версии»</strong>.</li><li>Кнопка <strong>«Завершить»</strong> блокируется, переводя Верстак в режим просмотра текущих очередей.</li><li>При этом возможность изменять приоритет заказов кнопками вверх/вниз и отменять запланированные задания сохраняется в полном объеме.</li><li>Для снятия блокировки достаточно активировать ключ бессрочной лицензии или подписки в глобальных Настройках программы.</li></ul><hr><h2 id="смежные-разделы-и-сквозная-навигация" tabindex="-1">Смежные разделы и сквозная навигация <a class="header-anchor" href="#смежные-разделы-и-сквозная-навигация" aria-label="Permalink to &quot;Смежные разделы и сквозная навигация&quot;">​</a></h2><ul><li><a href="/ru/docs/spaces/production/calculator">Калькулятор и рецепты изделий</a> — проектирование технологических карт, накладные расходы и запуск партий на верстак.</li><li><a href="/ru/docs/spaces/production/showcase">Склад готовых товаров</a> — партии готовой продукции, складской учет методом первых партий (ФИФО) и ручные инвентаризации.</li><li><a href="/ru/docs/resources/warehouse">Управление запасами сырья</a> — приходные накладные, распределение логистики и скользящая средняя стоимость (МАК).</li><li><a href="/ru/docs/spaces/production/cycle">Производственный цикл</a> — сквозное практическое руководство от закупки сырья до чека продажи.</li></ul>',39))])}const _=a(d,[["render",g]]);export{k as __pageData,_ as default};
